package com.easy1auth.adminidentity;
import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Component; import java.util.UUID;
/** PostgreSQL DELETE RETURNING is intentionally native to guarantee one-time code consumption. */
@Component final class RegistrationCodeNativeSql{private final JdbcClient db;RegistrationCodeNativeSql(JdbcClient db){this.db=db;}boolean consume(String email,String hash){return db.sql("delete from admin_registration_code where id in (select id from admin_registration_code where lower(email)=lower(:e) and code_hash=:h and expires_at>now() for update limit 1) returning id").param("e",email).param("h",hash).query(UUID.class).optional().isPresent();}void issue(UUID id,String email,String hash,java.time.Instant expires){db.sql("delete from admin_registration_code where lower(email)=lower(:e) or expires_at<=now()").param("e",email).update();db.sql("insert into admin_registration_code(id,email,code_hash,expires_at) values(:id,:e,:h,:x)").param("id",id).param("e",email).param("h",hash).param("x",expires).update();}}
